import json
import os
import pytest
import requests

# Point to the JSON file generated by our LLM and delta reporter
TEST_DATA_FILE = os.path.join(os.path.dirname(__file__), "pet_post_data.json")

def load_test_data():
    """Reads the AI-generated test cases from the JSON file."""
    if not os.path.exists(TEST_DATA_FILE):
        return []
    with open(TEST_DATA_FILE, "r", encoding="utf-8") as f:
        return json.load(f)

# Pytest will dynamically create a separate test execution for every object in the JSON array
@pytest.mark.parametrize(
    "test_case", 
    load_test_data(), 
    ids=lambda tc: tc.get("test_name", "unnamed_test")
)
def test_petstore_boundaries(test_case):
    url = "https://petstore.swagger.io/v2/pet"
    payload = test_case.get("payload", {})
    expected_status = test_case.get("expected_status", 400)
    
    headers = {"Content-Type": "application/json"}
    
    # Execute the API request using the AI-generated boundary payload
    response = requests.post(url, json=payload, headers=headers)
    
    # Assert the endpoint handles the edge case correctly
    assert response.status_code == expected_status, \
        f"Failed {test_case['test_name']}: Expected {expected_status}, got {response.status_code}. Data: {response.text}"